Import ListNotations.
Open Scope Z_scope.
Unset Lia Cache. Unset Nia Cache. Unset Nra Cache.
Local Ltac transport_chunks segs m a bs ::= transport_chunks_fast segs m a bs.
Local Ltac footprint_after_store segs m a bs ::= footprint_after_store_fast segs m a bs.
Local Ltac mem_after_store ::= mem_after_store_fast.
(* [comment removed for export] *)
Local Ltac norm_regset ::=
  repeat match goal with
  | |- context [@bvmap_set 5 word ?r ?v ?R] =>
      lazymatch R with TNode _ _ _ => idtac | TEmpty => idtac end;
      let p := eval vm_compute in (bv_key r) in
      change (@bvmap_set 5 word r v R) with (tset p v R);
      cbv beta iota delta [tset mkR]
  end.

(* [comment removed for export] *)
Record app : Type := mk_app {
  ap_DS : Z; ap_DD : Z; ap_N : Z;        (* [comment removed for export] *)
  ap_w : Z; ap_h : Z; ap_wpl : Z;
  ap_FW : Z; ap_FH : Z;                   (* [comment removed for export] *)
  ap_KI : Z; ap_KF : Z; ap_LS : Z;        (* [comment removed for export] *)
  ap_ks : list word; ap_lps : list Z; ap_ps : list pixe }.

(* [comment removed for export] *)
Definition arange (a n : Z) : Prop := 0 < a /\ a + n <= 2^47 /\ (a + n <= 0x7fff7000 \/ 0x10007fff8000 <= a) /\ (a + n <= 0x10000 \/ 0x662000 <= a).

Definition ap_ok (p : app) : Prop :=
  0 < ap_w p <= 20000 /\ 0 < ap_h p <= 20000 /\ ap_wpl p = (ap_w p * 8 + 31) / 32 /\ ap_N p = 4 * (ap_wpl p * ap_h p) /\ 0 < ap_N p <= 0x4000000
  /\ arange (ap_DS p) (ap_N p) /\ ap_DS p mod 4 = 0 /\ arange (ap_DD p) (ap_N p) /\ ap_DD p mod 4 = 0
  /\ arange (ap_FW p) 4 /\ ap_FW p mod 4 = 0 /\ arange (ap_FH p) 4 /\ ap_FH p mod 4 = 0
  /\ arange (ap_KI p) 1024 /\ ap_KI p mod 8 = 0 /\ arange (ap_KF p) 1024 /\ ap_KF p mod 8 = 0 /\ arange (ap_LS p) 80 /\ ap_LS p mod 8 = 0
  /\ kidx_ok 10 (ap_ks p) /\ length (ap_lps p) = 10%nat /\ length (ap_ps p) = 10%nat
  /\ Forall (fun lp => arange lp (8 * ap_h p) /\ lp mod 8 = 0) (ap_lps p)
  /\ Forall (fun e => p_w (pe_v e) = ap_w p /\ p_h (pe_v e) = ap_h p /\ p_wpl (pe_v e) = ap_wpl p
                     /\ arange (p_data (pe_v e)) (ap_N p) /\ p_data (pe_v e) mod 4 = 0) (ap_ps p)
  (* [comment removed for export] *)
  /\ (ap_DD p + ap_N p <= ap_DS p \/ ap_DS p + ap_N p <= ap_DD p)
  /\ (ap_DD p + ap_N p <= ap_FW p \/ ap_FW p + 4 <= ap_DD p) /\ (ap_DD p + ap_N p <= ap_FH p \/ ap_FH p + 4 <= ap_DD p)
  /\ (ap_DD p + ap_N p <= ap_KI p \/ ap_KI p + 1024 <= ap_DD p) /\ (ap_DD p + ap_N p <= ap_KF p \/ ap_KF p + 1024 <= ap_DD p)
  /\ (ap_DD p + ap_N p <= ap_LS p \/ ap_LS p + 80 <= ap_DD p)
  /\ Forall (fun lp => ap_DD p + ap_N p <= lp \/ lp + 8 * ap_h p <= ap_DD p) (ap_lps p)
  /\ Forall (fun e => ap_DD p + ap_N p <= p_data (pe_v e) \/ p_data (pe_v e) + ap_N p <= ap_DD p) (ap_ps p).

(* [comment removed for export] *)
Definition ap_ro (p : app) (m : mem) : Prop :=
  rw_cells asegs m (ap_FW p) [C4 (Z_to_bv 64 (ap_w p))] /\ rw_cells asegs m (ap_FH p) [C4 (Z_to_bv 64 (ap_h p))]
  /\ wr_at asegs m (ap_DS p) (ap_N p) /\ acc asegs m (ap_DS p) (ap_N p)
  /\ u32arr asegs m (ap_KI p) (ap_ks p) /\ acc asegs m (ap_KI p) 1024
  /\ wr_at asegs m (ap_KF p) 1024 /\ acc asegs m (ap_KF p) 1024
  /\ u64arr asegs m (ap_LS p) (map (Z_to_bv 64) (ap_lps p)) /\ acc asegs m (ap_LS p) 80
  /\ (forall k, 0 <= k < 10 -> exists lp e, nth_error (ap_lps p) (Z.to_nat k) = Some lp /\ nth_error (ap_ps p) (Z.to_nat k) = Some e
        /\ u64arr asegs m lp (row_ptrs (pe_v e)) /\ acc asegs m lp (8 * ap_h p)
        /\ wr_at asegs m (p_data (pe_v e)) (ap_N p) /\ acc asegs m (p_data (pe_v e)) (ap_N p)).

Lemma row_ptrs_nth : forall v i, 0 <= i < p_h v ->
  nth_error (row_ptrs v) (Z.to_nat i) = Some (Z_to_bv 64 (p_data v + 4 * p_wpl v * i)).
