(* [comment removed for export] *)
Definition hacc (m : mem) (a n : Z) : Prop := acc asegs m a n.
Ltac hide_accs := repeat match goal with H : acc asegs ?m ?a ?n |- _ => change (hacc m a n) in H end.
Ltac show_acc H := unfold hacc in H.
Definition hfact (P : Prop) : Prop := P.
Ltac hide_fact H := lazymatch type of H with ?t => change (hfact t) in H end.

(* [comment removed for export] *)
Definition ap_j_exit (p : app) (i LS LD : Z) (ra sp gp tp s0 s1 a0 s2 : word) (F : bvmap 5 word) (m : mem) : machine_state -> Prop :=
  fun ms' => exists (t2' a1' a2' t3' t4' t5' : word) (F' : bvmap 5 word) (fc' : bv 32) (m' : mem),
    ms' = MS (mkR ra sp gp tp (Z_to_bv 64 (LS + ap_w p)) (Z_to_bv 64 (LD + ap_w p)) t2' s0 s1 a0 a1' a2'
                  (Z_to_bv 64 i) (Z_to_bv 64 (4 * ap_wpl p)) (Z_to_bv 64 (ap_w p)) (Z_to_bv 64 (ap_w p)) (Z_to_bv 64 (8 * i)) s2 (Z_to_bv 64 (ap_FW p)) (Z_to_bv 64 1)
                  (Z_to_bv 64 LS) (Z_to_bv 64 LD) (Z_to_bv 64 (ap_LS p)) (Z_to_bv 64 (ap_KI p))
                  (Z_to_bv 64 (4 * ap_wpl p)) (Z_to_bv 64 (ap_KF p)) (Z_to_bv 64 2147450880) t3' t4' t5' (Z_to_bv 64 (ap_FH p)))
             F' (Z_to_bv 64 0xc3a48) fc' None m' (seg_rom asegs)
    /\ fs_agree F F' /\ frm0 fc' /\ munch [(ap_DD p, ap_DD p + ap_N p)] m m' /\ wmono asegs m m' /\ mem_inv asegs m'.

(* [comment removed for export] *)
Lemma ap_j_loop : forall (n : nat) (p : app) (i j LS LD : Z)
    (ra sp gp tp t2 s0 s1 a0 a1 a2 s2 t3 t4 t5 : word) (F : bvmap 5 word) (fc : bv 32) (m : mem),
  Z.of_nat n = ap_w p - j -> 0 <= j -> (1 <= n)%nat -> 0 <= i < ap_h p -> ap_ok p -> frm0 fc ->
  ap_DS p <= LS -> LS + 4 * ap_wpl p <= ap_DS p + ap_N p -> ap_DD p <= LD -> LD + 4 * ap_wpl p <= ap_DD p + ap_N p ->
  (forall m', munch [(ap_DD p, ap_DD p + ap_N p)] m m' -> wmono asegs m m' -> ap_ro p m') ->
  wr_at asegs m (ap_DD p) (ap_N p) -> acc asegs m (ap_DD p) (ap_N p) -> mem_inv asegs m ->
  evt asegs (ap_j_exit p i LS LD ra sp gp tp s0 s1 a0 s2 F m)
    (MS (mkR ra sp gp tp (Z_to_bv 64 (LS + j)) (Z_to_bv 64 (LD + j)) t2 s0 s1 a0 a1 a2
             (Z_to_bv 64 i) (Z_to_bv 64 (4 * ap_wpl p)) (Z_to_bv 64 j) (Z_to_bv 64 j) (Z_to_bv 64 (8 * i)) s2 (Z_to_bv 64 (ap_FW p)) (Z_to_bv 64 1)
             (Z_to_bv 64 LS) (Z_to_bv 64 LD) (Z_to_bv 64 (ap_LS p)) (Z_to_bv 64 (ap_KI p))
             (Z_to_bv 64 (4 * ap_wpl p)) (Z_to_bv 64 (ap_KF p)) (Z_to_bv 64 2147450880) t3 t4 t5 (Z_to_bv 64 (ap_FH p)))
        F (Z_to_bv 64 0xc3a7c) fc None m (seg_rom asegs)).
Proof.
