(* [comment removed for export] *)
Definition ap_i_exit (p : app) (ra sp gp tp s0 s1 a0 s2 : word) (F : bvmap 5 word) (m : mem) : machine_state -> Prop :=
  fun ms' => exists (t0' t1' t2' a1' a2' a5' a6' a7' t3' t4' t5' : word) (F' : bvmap 5 word) (fc' : bv 32) (m' : mem),
    ms' = MS (mkR ra sp gp tp t0' t1' t2' s0 s1 a0 a1' a2' (Z_to_bv 64 (ap_h p)) (Z_to_bv 64 (4 * ap_wpl p)) a5' a6' a7' s2 (Z_to_bv 64 (ap_FW p)) (Z_to_bv 64 1)
                  (Z_to_bv 64 (ap_DS p + 4 * ap_wpl p * ap_h p)) (Z_to_bv 64 (ap_DD p + 4 * ap_wpl p * ap_h p)) (Z_to_bv 64 (ap_LS p)) (Z_to_bv 64 (ap_KI p))
                  (Z_to_bv 64 (4 * ap_wpl p)) (Z_to_bv 64 (ap_KF p)) (Z_to_bv 64 2147450880) t3' t4' t5' (Z_to_bv 64 (ap_FH p)))
             F' (Z_to_bv 64 0xc3ca4) fc' None m' (seg_rom asegs)
    /\ fs_agree F F' /\ frm0 fc' /\ munch [(ap_DD p, ap_DD p + ap_N p)] m m' /\ wmono asegs m m' /\ mem_inv asegs m'.

(* [comment removed for export] *)
Lemma ap_i_loop : forall (n : nat) (p : app) (i LS LD : Z)
    (ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a5 a6 a7 s2 t3 t4 t5 : word) (F : bvmap 5 word) (fc : bv 32) (m : mem),
  Z.of_nat n = ap_h p - i -> 0 <= i -> (1 <= n)%nat -> ap_ok p -> frm0 fc ->
  LS = ap_DS p + 4 * ap_wpl p * i -> LD = ap_DD p + 4 * ap_wpl p * i ->
  (forall m', munch [(ap_DD p, ap_DD p + ap_N p)] m m' -> wmono asegs m m' -> ap_ro p m') ->
  wr_at asegs m (ap_DD p) (ap_N p) -> acc asegs m (ap_DD p) (ap_N p) -> mem_inv asegs m ->
  evt asegs (ap_i_exit p ra sp gp tp s0 s1 a0 s2 F m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 (Z_to_bv 64 i) (Z_to_bv 64 (4 * ap_wpl p)) a5 a6 a7 s2 (Z_to_bv 64 (ap_FW p)) (Z_to_bv 64 1)
             (Z_to_bv 64 LS) (Z_to_bv 64 LD) (Z_to_bv 64 (ap_LS p)) (Z_to_bv 64 (ap_KI p))
             (Z_to_bv 64 (4 * ap_wpl p)) (Z_to_bv 64 (ap_KF p)) (Z_to_bv 64 2147450880) t3 t4 t5 (Z_to_bv 64 (ap_FH p)))
